import java.util.*;class AlpineStreamsTest{public static void main(String[]a){int n=128;float[] h=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)h[z*n+x]=(float)(800-x*.5);var e=new EnvironmentMap(h.clone());e.ribbons=new RiverRibbon.Network(List.of(new RiverRibbon.Segment(new RiverRibbon.Point(0,0,3,62),new RiverRibbon.Point(0,8,3,62),2)));int[] parents=new int[n*n];Arrays.fill(parents,-1);var node=new TerrainGraph.Node(9,TerrainGraph.Type.RIVERS,0,0);node.values.put("alpineStreams",4.0);node.values.put("maxSlope",.18);AlpineStreams.generate(node,e,h,new EnvironmentNodes.Drainage(parents,h),n,1024,62,71,()->false);if(e.mountainArms.isEmpty())throw new AssertionError("No upper streams");double highest=0;for(var arm:e.mountainArms)for(var p:arm.points()){highest=Math.max(highest,p.water());if(RiverShape.height(h,n,p.x()/8,p.z()/8)-p.water()>2)throw new AssertionError("Deep stream incision");if(RiverCourse.terrainSlope(h,n,p.x()/8,p.z()/8,8)>.18)throw new AssertionError("Steep stream");}if(highest<790)throw new AssertionError("Stream starts too low");System.out.println("PASS: upper snowmelt streams start near summit and retain terrain-level water");}}
